import { useReducer } from 'react';

// Mock API:
let fetchCount = 0;
const mockFetchQuests = () => new Promise((resolve, reject) => {
  fetchCount++;
  setTimeout(() => {
    if (fetchCount % 2 === 0) {
      resolve([{ id: 1, title: 'Slay the Dragon' }, { id: 2, title: 'Find the Tome' }]);
    } else {
      reject(new Error('Server error'));
    }
  }, 800);
});

